function load(){try{const base=freshState(),raw=JSON.parse(localStorage.getItem(STORAGE)||'{}');const out={...base,...raw};out.adventure={...base.adventure,...(raw.adventure||{})};out.onboarding={...base.onboarding,...(raw.onboarding||{})};if(out.starter)out.onboarding.starterChosen=true;if(out.adventure.completed&&out.adventure.completed.first_shard)out.onboarding.tutorialComplete=true;return out}catch{return freshState()}}function save(){localStorage.setItem(STORAGE,JSON.stringify(S));renderCurrencies();}
function toast(t){const x=$('toast');x.textContent=t;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),2400)}
function factionOfCard(id){return allCards.find(c=>c.id===id)?.faction} function cardById(id){return allCards.find(c=>c.id===id)} function owned(id){return S.owned[id]||0}
function rarityClass(r){return 'rarity'+r} function fc(f){return FACTIONS[f].colors[0]}
