function featureUnlocked(view){if(view==='home'||view==='adventure')return true;if(!S.onboarding.tutorialComplete)return false;if(view==='collection'||view==='play')return true;if(view==='decks')return !!S.adventure.completed.pack_trail;if(view==='rewards')return !!S.adventure.completed.iron_gate;if(view==='shop')return !!S.adventure.completed.veil_path;return true}
function refreshNavLocks(){document.querySelectorAll('#nav button').forEach(b=>{const ok=featureUnlocked(b.dataset.view);b.classList.toggle('locked',!ok);b.title=ok?'':({collection:'Complete The First Shard to unlock Collection.',play:'Complete The First Shard to unlock Practice.',decks:'Complete the Mahirim Trial to unlock Deck Builder.',rewards:'Complete the Dwarf Trial to unlock Progression.',shop:'Complete the Alfar Trial to unlock the Store.'}[b.dataset.view]||'Continue Adventure to unlock.')})}
function showGuide(title,text,visual='',cb=null,kicker='SHARDBEARER GUIDE'){guideCallback=cb;$('guideKicker').textContent=kicker;$('guideTitle').textContent=title;$('guideText').textContent=text;$('guideVisual').innerHTML=visual;$('guideModal').classList.add('show')}
function closeGuide(){$('guideModal').classList.remove('show');const cb=guideCallback;guideCallback=null;if(cb)cb()}
function showIntro(force=false){if(S.onboarding.introSeen&&!force)return;introIndex=0;renderIntro();$('introModal').classList.add('show');clearTimeout(introTimer);introTimer=setTimeout(()=>{},1)}
function renderIntro(){const s=INTRO_SCENES[introIndex];clearTimeout(introTimer);$('introScene').style.backgroundImage=`url('${s.img}')`;$('introKicker').textContent=s.k;$('introTitle').textContent=s.title;$('introText').textContent=s.text;$('introProgress').innerHTML=INTRO_SCENES.map((_,i)=>`<span class="${i<=introIndex?'on':''}"></span>`).join('');$('introNext').textContent=introIndex===INTRO_SCENES.length-1?'Begin Journey':'Continue';if(introIndex<INTRO_SCENES.length-1)introTimer=setTimeout(advanceIntro,6500)}
function advanceIntro(){if(introIndex<INTRO_SCENES.length-1){introIndex++;renderIntro();return}finishIntro()}
function finishIntro(){clearTimeout(introTimer);$('introModal').classList.remove('show');S.onboarding.introSeen=true;save();if(!S.onboarding.tutorialComplete){nav('adventure');setTimeout(()=>showGuide('Your first battle is a lesson','Start with The First Shard. We will teach Energy, cards, Ready/Exhausted creatures, Frontline and how to win as they appear.','<b>Tip:</b> The tutorial uses a temporary Mercian training deck, so you do not need to choose a faction yet.'),250)}else if(!S.starter)starter()}
function maybeFirstVisit(view){if(view==='collection'&&!S.onboarding.collectionSeen){S.onboarding.collectionSeen=true;save();showGuide('This is your Collection','Every card you own lives here. Tap a card to inspect its cost, stats and ability. You can eventually earn or craft every gameplay card.','<b>Owned / 3</b> shows how many playable copies you have.')}if(view==='decks'&&!S.onboarding.decksSeen){S.onboarding.decksSeen=true;save();showGuide('Build a 30-card deck','Choose one faction, pick a Shardbound Leader, and add up to 3 copies of a card. The Energy Curve helps you avoid a deck that is too expensive.','<b>Goal:</b> exactly 30 cards • maximum 3 copies.')}if(view==='rewards'&&!S.onboarding.rewardsSeen){S.onboarding.rewardsSeen=true;save();showGuide('Everything you do should move you forward','Faction Mastery, quests and Adventure rewards grow your collection even before competitive play exists.')}if(view==='shop'&&!S.onboarding.shopSeen){S.onboarding.shopSeen=true;save();showGuide('Cards are not cash-exclusive','Aether Caches add variety. Shard Dust lets you craft a specific missing card, so random packs are never the only path.')}}
function renderCurrencies(){$('goldSide').textContent=$('goldTop').textContent=S.gold;$('dustSide').textContent=$('dustTop').textContent=S.dust;$('packsTop').textContent=S.packs;$('profileLine').textContent=S.starter?`${S.starter} Initiate • Account Lv. 3`:'Choose a starter faction'}
function nav(view){if(!featureUnlocked(view)){toast('That area unlocks as you continue Chapter One.');return}document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('viewTitle').textContent=({home:'Home',adventure:'Adventure',collection:'Collection',decks:'Deck Builder',play:'Play',rewards:'Progression',shop:'Store'})[view]||view;if(view==='collection')renderCollection();if(view==='decks')renderDeckBuilder();if(view==='play')renderPlay();if(view==='rewards')renderRewards();if(view==='shop')renderPack();refreshNavLocks();window.scrollTo(0,0);setTimeout(()=>maybeFirstVisit(view),160)}
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));
function starter(force=false){if(S.starter&&!force)return;const g=$('starterGrid');g.innerHTML='';for(const [f,d] of Object.entries(FACTIONS)){const info=FACTION_NPE[f];const el=document.createElement('div');el.className='starter'+(recommendedFaction===f?' recommended':'');el.style.setProperty('--fc',fc(f));el.innerHTML=`<img src="${LEADER_ART[f]}" alt="${f} Leader"><h3>${f}</h3><span class="starter-style">${info.style}</span><div class="starter-fit">${info.fit}</div><div class="small muted" style="margin-top:7px">Leader passive: ${d.passive}</div>${recommendedFaction===f?'<div class="tag live" style="margin-top:8px">RECOMMENDED</div>':''}`;el.onclick=()=>chooseStarter(f);g.appendChild(el)}$('starterModal').classList.add('show')}
function chooseStarter(f){S.starter=f;S.onboarding.starterChosen=true;for(const c of FACTIONS[f].cards)S.owned[c.id]=3;for(const [of,d] of Object.entries(FACTIONS))if(of!==f)for(const c of d.cards.slice(0,2))S.owned[c.id]=1;S.mastery[f]=1;const cards={};for(const c of FACTIONS[f].cards)cards[c.id]=3;S.decks=[{id:'starter',name:`${f} Starter`,faction:f,cards}];editDeck=JSON.parse(JSON.stringify(S.decks[0]));save();$('starterModal').classList.remove('show');renderAll();refreshNavLocks();nav('home');showGuide(`${f} starter unlocked`,`You now own a complete ${f} starter deck. Your next goal is to continue Chapter One; Collection is also available whenever you want to inspect your cards.`,`<b>${FACTION_NPE[f].style}</b><br>${FACTION_NPE[f].fit}`);toast(`${f} starter deck unlocked.`)}
function renderHome(){const unique=allCards.filter(c=>owned(c.id)>0).length;$('collectionCount').textContent=`${unique}/60`;$('collectionMilestone').style.width=Math.min(100,unique/30*100)+'%';$('homeQuests').innerHTML=S.quests.slice(0,3).map(q=>`<div class="quest"><div><b>${q.name}</b><div class="bar"><span style="width:${Math.min(100,q.p/q.max*100)}%"></span></div></div><span class="tag">${q.p}/${q.max}</span></div>`).join('');const f=S.starter||'Mahirim';const m=S.mastery[f]||0;$('homeMastery').innerHTML=`<div class="leader-chip" style="--fc:${fc(f)}"><img src="${LEADER_ART[f]}"><div><b>${f}</b><div class="small muted">Mastery Level ${m}</div><div class="bar"><span style="width:${Math.min(100,m*18)}%"></span></div></div></div>`;$('homeHero').style.setProperty('--hero',`url(assets/ui/home-banner.jpg)`)}
function keywordify(text){let out=text;for(const k of Object.keys(KEYWORDS)){out=out.replace(new RegExp(`\b${k}\b`,'g'),`<button class="keyword-link" data-keyword="${k}" type="button">${k}</button>`)}return out}
function cardHTML(c,forDeck=false){const qty=owned(c.id),rar=c.rarity,art=CARD_ART[c.id]||'';return `<div class="card ${qty?'':'locked'}" data-card="${c.id}" style="--fc:${fc(c.faction)}"><div class="card-art"><img src="${art}" alt="" loading="lazy"><div class="art-shade"></div><div class="cost"><span>${c.cost}</span></div><div class="faction-mark">${FACTIONS[c.faction].sigil}</div><div class="rarity-gem ${rarityClass(rar)}" title="${rar}"></div>${c.type==='Creature'?`<div class="card-stats"><span class="atk">⚔ ${c.atk}</span><span class="hp">♥ ${c.hp}</span></div>`:''}</div><div class="card-body"><div class="card-name">${c.name}</div><div class="card-meta">${c.type} • ${c.faction}</div><div class="owned">${forDeck?`Owned ${qty} • In deck ${editDeck.cards[c.id]||0}`:`Owned ${qty}/3`}</div></div></div>`}
function filteredCards(){const q=$('cardSearch').value.toLowerCase(),f=$('factionFilter').value,t=$('typeFilter').value,r=$('rarityFilter').value,o=$('ownedFilter').value;return allCards.filter(c=>(!q||c.name.toLowerCase().includes(q)||c.desc.toLowerCase().includes(q))&&(f==='All'||c.faction===f)&&(t==='All'||c.type===t)&&(r==='All'||c.rarity===r)&&(o==='All'||(o==='Owned'?owned(c.id)>0:owned(c.id)===0)))}
function renderCollection(){const arr=filteredCards();$('collectionGrid').innerHTML=arr.map(c=>cardHTML(c)).join('');document.querySelectorAll('#collectionGrid [data-card]').forEach(el=>el.onclick=()=>{selectedCard=cardById(el.dataset.card);renderDetail()});renderDetail()}
function renderDetail(){const c=selectedCard;if(!c)return;$('cardDetail').style.setProperty('--fc',fc(c.faction));const need=dustCost[c.rarity],art=CARD_ART[c.id]||'';$('cardDetail').innerHTML=`<div class="detail-art"><img src="${art}" alt="${c.name}"><div class="detail-shade"></div><div class="cost"><span>${c.cost}</span></div><div class="detail-sigil">${FACTIONS[c.faction].sigil}</div>${c.type==='Creature'?`<div class="detail-stats"><span>⚔ ${c.atk}</span><span>♥ ${c.hp}</span></div>`:''}</div><div class="small ${rarityClass(c.rarity)}" style="margin-top:9px">${c.rarity.toUpperCase()} • ${c.faction}</div><h2>${c.name}</h2><div class="card-meta">${c.type}${c.type==='Creature'?` • ${c.atk} ATK / ${c.hp} HP`:''}</div><p class="rules">${keywordify(c.desc)}</p><div class="quest"><div><b>Owned</b></div><span>${owned(c.id)}/3</span></div><button class="btn primary" id="craftCard" ${owned(c.id)>=3||S.dust<need?'disabled':''}>Craft 1 • ${need} Dust</button>`;document.querySelectorAll('#cardDetail [data-keyword]').forEach(k=>k.onclick=()=>showGuide(k.dataset.keyword,KEYWORDS[k.dataset.keyword]||'See Help for details.','','','KEYWORD'));const b=$('craftCard');if(b)b.onclick=()=>{if(owned(c.id)>=3||S.dust<need)return;S.dust-=need;S.owned[c.id]=(S.owned[c.id]||0)+1;save();renderCollection();toast(`${c.name} crafted.`)}}
function renderDeckBuilder(){const f=editDeck.faction||S.starter||'Mahirim';editDeck.faction=f;$('deckFaction').value=f;$('deckName').value=editDeck.name||'My Deck';$('deckPool').innerHTML=FACTIONS[f].cards.map(c=>cardHTML(c,true)).join('');document.querySelectorAll('#deckPool [data-card]').forEach(el=>el.onclick=()=>addCard(el.dataset.card));const L=FACTIONS[f];$('leaderDeck').innerHTML=`<div class="leader-chip" style="--fc:${fc(f)}"><img src="${LEADER_ART[f]}"><div><b>${L.leader}</b><div class="small muted">${L.passive}</div></div></div>`;renderDeckList()}
function deckTotal(){return Object.values(editDeck.cards||{}).reduce((a,b)=>a+b,0)}
function addCard(id){if(factionOfCard(id)!==editDeck.faction)return;const q=editDeck.cards[id]||0;if(q>=3||q>=owned(id)||deckTotal()>=30){toast(q>=owned(id)?'You need to acquire another copy first.':'Deck limit reached.');return}editDeck.cards[id]=q+1;renderDeckBuilder()}
function removeCard(id){if(!editDeck.cards[id])return;editDeck.cards[id]--;if(editDeck.cards[id]<=0)delete editDeck.cards[id];renderDeckBuilder()}
function renderDeckList(){const total=deckTotal();$('deckCount').textContent=`${total}/30`;$('deckStatus').textContent=total===30?'READY':'INCOMPLETE';$('deckStatus').classList.toggle('live',total===30);const rows=Object.entries(editDeck.cards).filter(([,q])=>q>0).sort((a,b)=>cardById(a[0]).cost-cardById(b[0]).cost).map(([id,q])=>{const c=cardById(id);return `<div class="deckrow"><div><b>${c.name}</b><div class="small muted">${c.cost} • ${c.type}</div></div><b>x${q}</b><button data-minus="${id}">−</button></div>`}).join('');$('deckRows').innerHTML=rows||'<p class="muted">Click owned cards to add them.</p>';document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>removeCard(b.dataset.minus));const curve=Array(8).fill(0);for(const [id,q] of Object.entries(editDeck.cards)){const c=cardById(id);curve[Math.min(7,c.cost-1)]+=q}const max=Math.max(1,...curve);$('curve').innerHTML=curve.map((n,i)=>`<div class="curve-col"><div class="curve-bar" style="height:${n/max*62}px"></div>${i===7?'8+':i+1}<br>${n}</div>`).join('')}
$('saveDeck').onclick=()=>{editDeck.name=$('deckName').value.trim()||'My Deck';if(deckTotal()!==30){toast('A legal deck needs exactly 30 cards.');return}const id=editDeck.id||'d'+Date.now();editDeck.id=id;const ix=S.decks.findIndex(d=>d.id===id);if(ix>=0)S.decks[ix]=JSON.parse(JSON.stringify(editDeck));else S.decks.push(JSON.parse(JSON.stringify(editDeck)));save();renderPlay();toast('Deck saved.')};$('deckFaction').onchange=e=>{const f=e.target.value;editDeck={name:`${f} Deck`,faction:f,cards:{}};renderDeckBuilder()};
function renderPlay(){const sel=$('playDeckSelect');sel.innerHTML=S.decks.map(d=>`<option value="${d.id}">${d.name} • ${d.faction} • ${Object.values(d.cards).reduce((a,b)=>a+b,0)}/30</option>`).join('')||'<option>No saved decks</option>';if(S.decks.length)sel.value=S.decks[0].id;$('opponentSelect').innerHTML=Object.keys(FACTIONS).map(f=>`<option>${f}</option>`).join('');$('opponentSelect').value='Orks';updatePlayDeckInfo();sel.onchange=updatePlayDeckInfo}
function updatePlayDeckInfo(){const d=S.decks.find(x=>x.id===$('playDeckSelect').value);if(!d){$('playDeckInfo').innerHTML='<p class="muted">Save a deck first.</p>';return}const f=FACTIONS[d.faction];$('playDeckInfo').innerHTML=`<div class="leader-chip" style="--fc:${fc(d.faction)}"><img src="${LEADER_ART[d.faction]}"><div><b>${d.name}</b><div class="small muted">${d.faction} • ${f.leader}</div></div></div><p class="small muted">Your saved 30-card deck is passed directly into the battle engine.</p>`}
$('launchBattle').onclick=()=>{const d=S.decks.find(x=>x.id===$('playDeckSelect').value);if(!d){toast('Save a deck first.');return}if(Object.values(d.cards).reduce((a,b)=>a+b,0)!==30){toast('Only complete 30-card decks can enter battle.');return}const custom=[];for(const [id,q] of Object.entries(d.cards)){const c=cardById(id);for(let i=0;i<q;i++)custom.push(c.name)}const fr=$('battleFrame');fr.onload=()=>{try{const win=fr.contentWindow,doc=fr.contentDocument;win.__CUSTOM_PLAYER_DECK=custom;doc.getElementById('playerFaction').value=d.faction;doc.getElementById('enemyFaction').value=$('opponentSelect').value;doc.getElementById('startBtn').click()}catch(e){toast('Battle handoff failed.')}};fr.src=BATTLE_URL+'?t='+Date.now();$('battleModal').classList.add('show');S.quests[0].p=Math.min(S.quests[0].max,S.quests[0].p+1);S.mastery[d.faction]=(S.mastery[d.faction]||0)+0.2;save();renderHome()};$('closeBattle').onclick=()=>{$('battleModal').classList.remove('show');$('battleFrame').src='about:blank'};$('storyNext').onclick=closeStory;$('resultContinue').onclick=()=>{const n=resultEncounter,won=!!(S.adventure.lastResult&&n&&S.adventure.lastResult.encounterId===n.id&&S.adventure.lastResult.won);$('resultModal').classList.remove('show');if(won&&n&&n.id==='first_shard'){S.onboarding.tutorialComplete=true;save();refreshNavLocks();const after=()=>{if(!S.starter)starter();else{nav('adventure');renderAdventure()}};if(n.post)showStory(n,'post',after);else after();return}if(won&&n&&n.post)showStory(n,'post',()=>{nav('adventure');renderAdventure()});else{nav('adventure');renderAdventure()}};$('resultReplay').onclick=()=>{const n=resultEncounter;$('resultModal').classList.remove('show');if(n)launchAdventureEncounter(n)};
function renderRewards(){$('masteryGrid').innerHTML=Object.entries(FACTIONS).map(([f,d])=>{const m=S.mastery[f]||0;return `<div class="mastery" style="--fc:${fc(f)}"><div class="sig" style="color:${fc(f)}">${d.sigil}</div><b>${f}</b><div class="lvl">Lv ${Math.floor(m)}</div><div class="bar"><span style="width:${(m%1)*100}%"></span></div><div class="small muted">Next: card / cosmetic reward</div></div>`}).join('');$('questList').innerHTML=S.quests.map(q=>`<div class="quest"><div><b>${q.name}</b><div class="small muted">Reward: ${q.reward}</div><div class="bar"><span style="width:${q.p/q.max*100}%"></span></div></div><span class="tag">${q.p}/${q.max}</span></div>`).join('')}
function weightedCard(minRare=false){let pools=minRare?allCards.filter(c=>c.rarity!=='Common'):allCards;const weights={Common:62,Rare:26,Epic:9,Legendary:3};if(minRare) return pools[Math.floor(Math.random()*pools.length)];let r=Math.random()*100,rar='Common';for(const x of ['Common','Rare','Epic','Legendary']){r-=weights[x];if(r<=0){rar=x;break}}const p=allCards.filter(c=>c.rarity===rar);return p[Math.floor(Math.random()*p.length)]}
function acquire(c){if(owned(c.id)>=3){const d=dustDuplicate[c.rarity];S.dust+=d;return {card:c,dust:d}}S.owned[c.id]=(S.owned[c.id]||0)+1;return {card:c,dust:0}}
function openPack(useGold=false){const doOpen=()=>{if(useGold){if(S.gold<100){toast('Not enough Gold.');return}S.gold-=100}else{if(S.packs<1){toast('No earned packs available.');return}S.packs--}const pulls=[weightedCard(),weightedCard(),weightedCard(),weightedCard(),weightedCard(true)].map(acquire);S.lastPack=pulls;S.onboarding.firstPackExplained=true;save();renderPack();renderCollection();renderHome();toast('Aether Cache opened.')};if(!S.onboarding.firstPackExplained){showGuide('Aether Caches add cards to your collection','Each Cache contains 5 digital cards with at least one Rare-or-better. If you already own the maximum playable copies, the extra becomes Shard Dust instead.','<b>Shard Dust = choice.</b><br>Use it to craft the exact card you want.',doOpen,'FIRST AETHER CACHE');return}doOpen()}
function renderPack(){$('packResults').innerHTML=S.lastPack?.length?S.lastPack.map(x=>`<div class="pack-card"><div class="${rarityClass(x.card.rarity)} small">${x.card.rarity}</div><b>${x.card.name}</b><div class="small muted">${x.card.faction} • ${x.card.type}</div>${x.dust?`<div class="small gold" style="margin-top:7px">Duplicate → +${x.dust} Dust</div>`:`<div class="small" style="margin-top:7px">Added to Collection</div>`}</div>`).join(''):'<p class="muted">Open a pack to preview the acquisition loop.</p>'}
$('openEarnedPack').onclick=()=>openPack(false);$('openHomePack').onclick=()=>openPack(false);$('buyGoldPack').onclick=()=>openPack(true);

