for(const n of ADVENTURE){const m=ADVENTURE_META[n.id]||{};Object.assign(n,m)}
function adventureIndex(id){return ADVENTURE.findIndex(x=>x.id===id)}
function ensureAdventureState(){if(!S.adventure)S.adventure={completed:{},selected:'first_shard',lastResult:null,stars:{}};S.adventure.completed=S.adventure.completed||{};S.adventure.stars=S.adventure.stars||{}}
function objectiveDone(o,r){if(!r)return false;if(o.t==='win')return !!r.won;if(o.t==='hp')return !!r.won&&r.playerHp>=o.v;if(o.t==='round')return !!r.won&&r.round<=o.v;if(o.t==='ascend')return !!r.won&&((r.ascensions||0)+(r.leaderAscensions||0))>=o.v;return false}
function scoreObjectives(n,r){const objs=n.objectives||[{t:'win',label:'Win the battle'}];const done=objs.map(o=>objectiveDone(o,r));return {done,stars:done.filter(Boolean).length,objs}}
function starsHTML(n){const k=(S.adventure.stars&&S.adventure.stars[n.id])||0;return `<div class="encounter-stars">${[1,2,3].map(i=>`<span class="star ${i<=k?'on':''}">★</span>`).join('')}</div>`}
function showStory(n,mode,cb){storyCallback=cb||null;const boss=!!n.bossPortrait;const faction=n.portraitFaction||n.faction;$('storyTop').style.setProperty('--sc',boss?'#c53b55':fc(faction));$('storyPortrait').src=boss?BOSS_ART:LEADER_ART[faction];$('storyPortrait').alt=boss?n.name:`${n.speaker||faction} portrait`;$('storyKicker').textContent=mode==='post'?'AFTER THE BATTLE':n.boss?'CHAPTER BOSS':'BEFORE THE BATTLE';$('storySpeaker').textContent=n.speaker||n.name;$('storyText').textContent=mode==='post'?(n.post||'The path ahead opens.'):(n.pre||n.story);$('storyNext').textContent=mode==='post'?'Continue':'Enter Battle';$('storyModal').classList.add('show')}
function closeStory(){ $('storyModal').classList.remove('show');const cb=storyCallback;storyCallback=null;if(cb)cb()}
function showResult(n,r,firstClear,bonus){resultEncounter=n;const sc=scoreObjectives(n,r);$('resultKicker').textContent=r.won?'ENCOUNTER COMPLETE':'ENCOUNTER FAILED';$('resultTitle').textContent=r.won?'Victory':'Defeat';$('resultStars').innerHTML=[1,2,3].map(i=>`<span class="${i<=sc.stars?'on':'off'}">★</span>`).join('');$('resultSummary').textContent=r.won?`Round ${r.round} • ${r.playerHp} Leader HP remaining`:`Reached Round ${r.round}`;$('resultObjectives').innerHTML=sc.objs.map((o,i)=>`<div class="objective ${sc.done[i]?'done':''}"><span class="check">${sc.done[i]?'✓':'○'}</span><span>${o.label}</span></div>`).join('');$('resultRewards').innerHTML=r.won&&firstClear?rewardSummary(n.rewards).map(x=>`<span class="rewardpill">${x}</span>`).join(''):'<span class="small muted">Major rewards are granted on first clear.</span>';$('resultBonus').textContent=bonus||'';$('resultReplay').style.display='';$('resultReplay').textContent=r.won?'Replay':'Retry';$('resultContinue').textContent=r.won?'Continue':'Return to Map';$('resultModal').classList.add('show')}

function isEncounterUnlocked(i){if(i===0)return true;return !!S.adventure.completed[ADVENTURE[i-1].id]}
function rewardSummary(r){const out=[];if(r.gold)out.push(`◉ ${r.gold} Gold`);if(r.dust)out.push(`✦ ${r.dust} Dust`);if(r.packs)out.push(`◇ ${r.packs} Aether Cache`);if(r.card){const c=cardById(r.card);if(c)out.push(`▣ ${c.name}`)}return out}
function renderAdventure(){ensureAdventureState();let selected=ADVENTURE.find(x=>x.id===S.adventure.selected)||ADVENTURE[0];let idx=adventureIndex(selected.id);if(!isEncounterUnlocked(idx)){selected=ADVENTURE[Math.max(0,idx-1)];S.adventure.selected=selected.id;idx=adventureIndex(selected.id)}const comp=ADVENTURE.filter(x=>S.adventure.completed[x.id]).length;$('chapterProgress').innerHTML=ADVENTURE.map((x,i)=>`<span class="${S.adventure.completed[x.id]?'on':''}"></span>`).join('');const routes=[];for(let i=0;i<ADVENTURE.length-1;i++){const a=ADVENTURE[i],b=ADVENTURE[i+1],dx=b.x-a.x,dy=b.y-a.y,len=Math.sqrt(dx*dx+dy*dy),ang=Math.atan2(dy,dx)*180/Math.PI;routes.push(`<div class="route" style="left:${a.x}%;top:${a.y}%;width:${len}%;transform:rotate(${ang}deg)"></div>`)}$('routeLayer').innerHTML=routes.join('');$('nodeLayer').innerHTML=ADVENTURE.map((n,i)=>{const unlock=isEncounterUnlocked(i),done=!!S.adventure.completed[n.id];return `<div class="adventure-node" style="left:${n.x}%;top:${n.y}%;--nc:${fc(n.faction)}"><button class="node-btn ${n.boss?'boss ':''}${done?'complete':unlock?'unlocked':'locked'}" data-enc="${n.id}" ${unlock?'':'disabled'}>${done?'✓':n.sigil}</button><div class="node-label">${n.name}</div><div class="node-sub">${done?'Complete':unlock?n.sub:'Locked'}</div>${done?`<div class="star-summary">${'★'.repeat((S.adventure.stars[n.id]||0))}${'☆'.repeat(3-(S.adventure.stars[n.id]||0))}</div>`:''}</div>`}).join('');document.querySelectorAll('[data-enc]').forEach(b=>b.onclick=()=>{S.adventure.selected=b.dataset.enc;save();renderAdventure()});renderAdventureDeckSelect();renderEncounter(selected);const totalStars=Object.values(S.adventure.stars||{}).reduce((a,b)=>a+b,0);$('chapterRewards').innerHTML=`<span class="rewardpill">${comp}/${ADVENTURE.length} cleared</span><span class="rewardpill">★ ${totalStars}/${ADVENTURE.length*3} stars</span><span class="rewardpill">Boss reward: 1 Cache</span><span class="rewardpill">Guaranteed cards</span>`}
function renderAdventureDeckSelect(){const sel=$('adventureDeckSelect');const current=sel.value;const legal=S.decks.filter(d=>Object.values(d.cards).reduce((a,b)=>a+b,0)===30);const training=!S.starter&&!S.onboarding.tutorialComplete?'<option value="__training__">Shardbearer Training Deck • Mercians</option>':'';sel.innerHTML=training+legal.map(d=>`<option value="${d.id}">${d.name} • ${d.faction}</option>`).join('')||'<option value="">No legal saved deck</option>';if(current&&[...sel.options].some(o=>o.value===current))sel.value=current}
function renderEncounter(n){const r=rewardSummary(n.rewards),done=!!S.adventure.completed[n.id],last=S.adventure.lastResult&&S.adventure.lastResult.encounterId===n.id?S.adventure.lastResult:null;const preview=last?scoreObjectives(n,last):null;$('encounterPanel').style.setProperty('--ec',fc(n.faction));const banner=n.boss?`<img class="boss-art-banner" src="${BOSS_ART}" alt="Worldshard Behemoth">`:`<div class="encounter-banner" style="--ec:${fc(n.faction)}">${n.sigil}</div>`;$('encounterPanel').innerHTML=`${banner}<div class="small gold" style="margin-top:10px">${n.boss?'CHAPTER BOSS':n.sub.toUpperCase()}</div><h2>${n.title}</h2>${starsHTML(n)}<p class="story-card" style="--ec:${fc(n.faction)}">${n.story}</p><div class="objective-list">${(n.objectives||[]).map((o,i)=>`<div class="objective ${preview&&preview.done[i]?'done':''}"><span class="check">${preview&&preview.done[i]?'✓':i+1}</span><span>${o.label}</span></div>`).join('')}</div>${n.tips?`<div class="tutorial-steps">${n.tips.map((t,i)=>`<div class="tutorial-step"><b>${i+1}</b><div>${t}</div></div>`).join('')}</div>`:''}<div class="rewardline">${r.map(x=>`<span class="rewardpill">${x}</span>`).join('')}</div>${n.ruleText?`<div class="${n.boss?'boss-rule':'small muted'}">${n.ruleText}</div>`:''}${last?`<div class="adventure-result ${last.won?'':'loss'}">${last.won?'Victory':'Defeat'} • Round ${last.round} • ${last.stars||0}/3 stars</div>`:''}<button class="btn ${n.boss?'gold':'primary'}" id="launchEncounter" style="margin-top:12px" ${$('adventureDeckSelect')&&!$('adventureDeckSelect').value?'disabled':''}>${done?'Replay Encounter':n.boss?'Challenge Boss':'Begin Encounter'}</button>`;setTimeout(()=>{const b=$('launchEncounter');if(b)b.onclick=()=>launchAdventureEncounter(n)},0)}
function grantAdventureRewards(n){if(S.adventure.completed[n.id])return;const r=n.rewards||{};S.gold+=(r.gold||0);S.dust+=(r.dust||0);S.packs+=(r.packs||0);if(r.card){const c=cardById(r.card);if(c)acquire(c)}S.adventure.completed[n.id]=true;const i=adventureIndex(n.id);if(i<ADVENTURE.length-1)S.adventure.selected=ADVENTURE[i+1].id;save();renderAll();toast(`First clear! ${rewardSummary(r).join(' • ')}`)}
function launchAdventureEncounter(n){showStory(n,'pre',()=>startAdventureBattle(n))}
function startAdventureBattle(n){const val=$('adventureDeckSelect').value;let d=S.decks.find(x=>x.id===val),playerFaction=d?.faction||'Mercians',custom=[];if(val==='__training__'&&n.id==='first_shard'){playerFaction='Mercians';for(const c of FACTIONS.Mercians.cards)for(let i=0;i<3;i++)custom.push(c.name)}else{if(!d){toast('Build and save a legal 30-card deck first.');return}for(const [id,q] of Object.entries(d.cards)){const c=cardById(id);for(let i=0;i<q;i++)custom.push(c.name)}}const cfg={id:n.id,title:n.title,enemyHp:n.enemyHp||30,enemyStartMaxEnergy:n.enemyStartMaxEnergy||0,playerStartMaxEnergy:n.playerStartMaxEnergy||0,bossPower:n.bossPower||null,bossName:n.bossName||null,ruleText:n.ruleText||'',tutorialSteps:n.tutorialSteps||[],tutorialOpening:n.tutorialOpening||[],guidedTutorial:!!n.guidedTutorial};const fr=$('battleFrame');fr.onload=()=>{try{const win=fr.contentWindow,doc=fr.contentDocument;win.__CUSTOM_PLAYER_DECK=custom;win.__PVE_CONFIG=cfg;doc.getElementById('playerFaction').value=playerFaction;doc.getElementById('enemyFaction').value=n.faction;doc.getElementById('startBtn').click()}catch(e){toast('Adventure battle handoff failed.')}};fr.src=BATTLE_URL+'?t='+Date.now();$('battleModal').classList.add('show')}
window.addEventListener('message',e=>{const m=e.data;if(!m||m.type!=='sr-pve-result'||!m.encounterId)return;const n=ADVENTURE.find(x=>x.id===m.encounterId);if(!n)return;ensureAdventureState();const firstClear=!S.adventure.completed[n.id];const r={encounterId:m.encounterId,won:!!m.won,round:m.round,playerHp:m.playerHp,ascensions:m.ascensions||0,leaderAscensions:m.leaderAscensions||0,phase2:!!m.phase2};const scored=scoreObjectives(n,r),oldStars=S.adventure.stars[n.id]||0,newStars=Math.max(oldStars,scored.stars);let bonus='';if(m.won&&newStars>oldStars){const gained=newStars-oldStars;S.dust+=gained*10;if(newStars===3&&oldStars<3){S.gold+=25;bonus=`Star bonus: +${gained*10} Dust +25 Gold for a 3-star clear.`}else bonus=`Star bonus: +${gained*10} Shard Dust.`;S.adventure.stars[n.id]=newStars}r.stars=scored.stars;S.adventure.lastResult=r;$('battleModal').classList.remove('show');$('battleFrame').src='about:blank';if(m.won){if(firstClear)grantAdventureRewards(n);S.mastery[n.faction]=(S.mastery[n.faction]||0)+0.35;save();renderCurrencies();renderAdventure();showResult(n,r,firstClear,bonus)}else{save();renderAdventure();showResult(n,r,false,'Adjust your deck or strategy and try again.')}});
function renderAll(){renderCurrencies();renderHome();renderAdventure();renderCollection();renderDeckBuilder();renderPlay();renderRewards();renderPack()}
for(const f of Object.keys(FACTIONS)){const o=document.createElement('option');o.value=f;o.textContent=f;$('factionFilter').appendChild(o.cloneNode(true));$('deckFaction').appendChild(o)}['cardSearch','factionFilter','typeFilter','rarityFilter','ownedFilter'].forEach(id=>$(id).addEventListener(id==='cardSearch'?'input':'change',renderCollection));
$('introNext').onclick=advanceIntro;$('introSkip').onclick=finishIntro;$('guideContinue').onclick=closeGuide;$('openHelp').onclick=()=>showHelp('basics');$('closeHelp').onclick=()=>$('helpModal').classList.remove('show');$('recommendFaction').onclick=()=>{$('quizOptions').innerHTML=[['I want a balanced deck while I learn','Mercians'],['I want to attack fast','Mahirim'],['I want to defend and build a fortress','Dwarves'],['I want to outsmart and disrupt people','Alfar'],['I want creatures that grow and transform','Mirdain'],['I want risky, huge damage turns','Orks']].map(([t,f])=>`<button class="quiz-option" data-rec="${f}"><b>${t}</b><span class="small muted">Recommend ${f}</span></button>`).join('');document.querySelectorAll('[data-rec]').forEach(b=>b.onclick=()=>{recommendedFaction=b.dataset.rec;$('quizModal').classList.remove('show');starter(true)});$('starterModal').classList.remove('show');$('quizModal').classList.add('show')};$('closeQuiz').onclick=()=>{$('quizModal').classList.remove('show');starter(true)};
function showHelp(tab='basics'){$('helpModal').classList.add('show');document.querySelectorAll('#helpTabs button').forEach(b=>b.classList.toggle('active',b.dataset.help===tab));const bodies={basics:`<div class="help-section"><div class="help-item"><b>Goal</b><div>Reduce the enemy Leader to 0 Health.</div></div><div class="help-item"><b>Energy</b><div>Your maximum Energy rises by 1 each turn up to 8 and refills at the start of the turn.</div></div><div class="help-item"><b>Creatures</b><div>Creatures normally wait a turn before attacking. Damage persists until healed.</div></div><div class="help-item"><b>Frontline</b><div>${KEYWORDS.Frontline}</div></div><div class="help-item"><b>Tactics & Relics</b><div>Tactics create immediate effects. A Relic remains in play and provides an ongoing effect.</div></div></div>`,keywords:`<div class="keyword-grid">${Object.entries(KEYWORDS).map(([k,v])=>`<div class="keyword-chip"><b>${k}</b><div class="small muted">${v}</div></div>`).join('')}</div>`,decks:`<div class="help-section"><div class="help-item"><b>30 cards</b><div>A legal deck contains exactly 30 cards from one faction.</div></div><div class="help-item"><b>Maximum 3 copies</b><div>You may include up to 3 copies of one card.</div></div><div class="help-item"><b>Leader</b><div>Your faction determines its Shardbound Leader and Leader passive.</div></div><div class="help-item"><b>Energy Curve</b><div>A mix of low, medium and high-cost cards helps you make useful plays every turn.</div></div></div>`,rewards:`<div class="help-section"><div class="help-item"><b>Gold</b><div>Earned through play and used for digital acquisition systems.</div></div><div class="help-item"><b>Shard Dust</b><div>Deterministic crafting currency. Use it to craft a specific missing card.</div></div><div class="help-item"><b>Aether Cache</b><div>A 5-card digital reward with a Rare-or-better card guaranteed in this prototype.</div></div><div class="help-item"><b>Faction Mastery</b><div>Playing a faction grows its mastery track and can unlock cards or cosmetics.</div></div></div>`,replay:`<div class="help-section"><button class="btn gold" id="replayIntro">Replay Lore Intro</button><button class="btn primary" id="replayTutorial">Replay The First Shard Tutorial</button><div class="help-item"><b>Your progress is safe.</b><div>Replaying onboarding does not delete your collection, decks or Adventure progress.</div></div></div>`};$('helpBody').innerHTML=bodies[tab]||bodies.basics;if(tab==='replay'){setTimeout(()=>{$('replayIntro').onclick=()=>{$('helpModal').classList.remove('show');showIntro(true)};$('replayTutorial').onclick=()=>{$('helpModal').classList.remove('show');S.adventure.selected='first_shard';save();nav('adventure');setTimeout(()=>showGuide('Replay the tutorial','Select The First Shard and begin the encounter. Your normal progress and rewards remain intact.'),150)}},0)}}
document.querySelectorAll('#helpTabs button').forEach(b=>b.onclick=()=>showHelp(b.dataset.help));
renderAll();refreshNavLocks();if(!S.onboarding.introSeen)setTimeout(()=>showIntro(),220);else if(!S.onboarding.tutorialComplete){nav('adventure');setTimeout(()=>showGuide('Continue with The First Shard','The guided tutorial is your next recommended step.'),250)}else if(!S.starter)setTimeout(()=>starter(),250);
